import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import UserStats from './UserStats';
import React from 'react';

describe('UserStats', () => {
  const users = [
    { id: 1, name: 'Alice', isActive: true },
    { id: 2, name: 'Bob', isActive: false },
    { id: 3, name: 'Charlie', isActive: true },
    { id: 4, name: 'Dave', isActive: true },
  ];

  it('renders active and inactive user counts correctly', () => {
    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 3')).toBeDefined();
    expect(screen.getByText('Inactive Users: 1')).toBeDefined();
    expect(screen.getByText('Active Percentage: 75.0%')).toBeDefined();
  });

  it('handles empty user list', () => {
    render(<UserStats users={[]} />);

    expect(screen.getByText('Active Users: 0')).toBeDefined();
    expect(screen.getByText('Inactive Users: 0')).toBeDefined();
    // Should be 0.0% to avoid division by zero or NaN
    // But checking implementation, I used toFixed(1) -> '0.0'
    expect(screen.getByText('Active Percentage: 0.0%')).toBeDefined();
  });
});

